// Data-driven routes: every service answers exactly what the pack lists for the test customer (status, body, delay).
// `data.json` is generated by build_data.py from the pack's test-customer file. Card services carry only the card
// number (service contract, section 5), so the customer is found through the card index.
import data from "./data.json";

const sleep = (s) => new Promise((r) => setTimeout(r, s * 1000));

function failure(code, text, type) {
  const guid = "mock-" + Date.now().toString(16);
  return { result: { guid, returnCode: code, messageText: text, code, message: text, type,
                     details: { guid, rootCause: type === "ERROR" ? "TechnicalError" : "NotFoundException", errorOrigin: "freya-bank-mock" } } };
}
const invalid = (field) => failure("INVALID_ARGUMENTS_ERROR", field + " cannot be empty", "ERROR");
const NOT_FOUND_TEXT = {
  FB_IVR_CHANNEL_102: "Müşteriye ait geçerli kart bilgisi bulunamadı.",
  FB_IVR_CHANNEL_120: "Kart bakiye servisi hatası: kart bulunamadı",
  FB_IVR_CHANNEL_121: "Ekstre haftası servisi hatası: kart bulunamadı",
  FB_IVR_CHANNEL_107: "Pdf dokümanı bulunamadı",
};

// A field comes in body.data (the contract); the body's top level and the query string are tolerated.
function field(body, query, name) {
  const d = body && typeof body.data === "object" && body.data ? body.data : null;
  let v = d && d[name] !== undefined ? d[name] : body && body[name] !== undefined ? body[name] : query.get(name);
  if (v === null || v === undefined) return "";
  v = String(v).trim();
  if (v.startsWith("{{") || v.startsWith("%7B%7B")) return "{{template}}";     // the panel's test button sends variables unfilled
  return v;
}
const digits = (s) => String(s).replace(/\D/g, "");

function sameCard(stored, given) {
  if (stored === given) return true;
  const sd = digits(stored), gd = digits(given);
  if (gd.length < 4) return false;
  if (gd.length >= 10) return sd.slice(0, 6) === gd.slice(0, 6) && sd.slice(-4) === gd.slice(-4);
  return sd.endsWith(gd);
}

function notFound(svc, json) {
  if (svc.notFound) return json(failure(svc.notFound, NOT_FOUND_TEXT[svc.notFound] || "Kayıt bulunamadı", "WARNING"), 404);
  return json(invalid(svc.keys[svc.keys.length - 1]), 400);
}

export const routes = Object.entries(data.services).map(([name, svc]) => ({
  method: "POST",
  paths: [svc.path, "/" + name, "/" + name.replace(/\./g, "/")],
  async handle({ query, body, json }) {
    const want = svc.keys.map((k) => field(body, query, k));
    for (let i = 0; i < want.length; i++) if (!want[i]) return json(invalid(svc.keys[i]), 400);
    const cardKeyed = svc.keys[0] === "cardNumber";
    // which customer: by customer number, or through the card index
    let no = cardKeyed ? "" : want[0];
    if (no === "{{template}}") no = Object.keys(data.customers)[0];
    if (cardKeyed) {
      const explicit = field(body, query, "customerNo");
      if (explicit && explicit !== "{{template}}" && data.customers[explicit]) no = explicit;
      else if (want[0] === "{{template}}") no = Object.keys(data.customers)[0];
      else {
        const hit = Object.keys(data.cards).find((c) => sameCard(c, want[0]));
        if (hit) no = data.cards[hit][0];
      }
    }
    const customer = data.customers[no];
    if (!customer) return notFound(svc, json);
    const table = customer.services[name];
    if (!table) return notFound(svc, json);
    const sel = cardKeyed ? want : want.slice(1);
    let answer = table[sel.join("|")];
    if (!answer && table[""] !== undefined) answer = table[""];                       // answer not keyed by card in the pack
    if (!answer) {
      for (const [k, a] of Object.entries(table)) {
        const parts = k.split("|");
        if (parts.length !== sel.length) continue;
        const ok = parts.every((p, i) => sel[i] === "{{template}}" || p === sel[i] || (i === 0 && svc.keys.includes("cardNumber") ? sameCard(p, sel[i]) : digits(sel[i]) !== "" && digits(sel[i]) === digits(p)));
        if (ok) { answer = a; break; }
      }
    }
    if (!answer) return notFound(svc, json);
    if (answer.delay) await sleep(Math.min(answer.delay, 25));
    return json(answer.body, answer.http);
  },
}));
